const modules=[{name:'文の土台',label:'まずは語順をつかむ',level:'初級',desc:'「何をする」「どんな状態」を短い文で。'},{name:'質問と否定',label:'会話の往復をつくる',level:'初級',desc:'聞く・答える・お願いするための基本。'},{name:'時間と経験',label:'いつ・もう・まだを伝える',level:'初級',desc:'時制に頼らないタイ語の時間表現。'},{name:'気持ちとやりとり',label:'自分の意図を伝える',level:'初中級',desc:'希望・可能・依頼を自然な会話に。'},{name:'説明を広げる',label:'理由・条件・比較をつなぐ',level:'中級',desc:'一文から、まとまりのある説明へ。'},{name:'自然な会話へ',label:'似た表現を使い分ける',level:'中級',desc:'日常と仕事で使える一歩深い文法。'}];
// One romanization convention: unmarked mid, à low, â falling, á high, ǎ rising.
const lessons=[];
function L(m,title,pattern,intro,points,examples,q,options,answer,why){lessons.push({id:lessons.length+1,m,title,pattern,intro,points,examples:examples.map(e=>({th:e[0],ro:e[1],ja:e[2],note:e[3]})),q,options,answer,why})}
L(0,'基本の語順：主語＋動詞＋目的語','人 ＋ 動作 ＋ 対象','日本語の「私はコーヒーを飲む」は、タイ語では「私・飲む・コーヒー」の順です。動詞の形は主語によって変わりません。',['話題の人が明らかなら、会話では主語を省けます。','ครับ / ค่ะは丁寧な語尾。男性話者はครับ、女性話者は平叙文でค่ะを使います。'],[['ผมกินข้าว','phǒm kin khâao','私はご飯を食べます。','กินは「食べる」、ข้าวは「ご飯」。'],['ดื่มกาแฟไหม','dʉ̀ʉm kaafɛɛ mǎi','コーヒー飲む？','主語を省いた自然な誘い。']], '「私はコーヒーを飲む」の語順は？',['ผมดื่มกาแฟ','กาแฟผมดื่ม','ดื่มผมกาแฟ'],0,'基本は主語＋動詞＋目的語。ผม＋ดื่ม＋กาแฟです。');
L(0,'状態を言う：形容詞が述語になる','人・物 ＋ 状態','「暑い」「忙しい」は、そのまま文の述語になります。英語の be にあたる語を毎回入れる必要はありません。',['状態を述べるときは通常เป็นを入れません。','มาก「とても」は状態を表す語の後ろに置きます。'],[['วันนี้ร้อนมาก','wan níi rɔ́ɔn mâak','今日はとても暑い。','時間＋状態＋程度の順。'],['ช่วงนี้งานยุ่ง','chûaŋ níi ŋaan yûŋ','最近、仕事が忙しい。','ช่วงนี้は「このところ」。']], '「今日はとても暑い」は？',['วันนี้เป็นร้อนมาก','วันนี้ร้อนมาก','มากวันนี้ร้อน'],1,'ร้อนがそのまま「暑い」という述語になります。');
L(0,'名詞を説明する：修飾語は後ろ','名詞 ＋ 説明','「おいしい店」「この機械」の説明は、基本的に名詞の後ろに置きます。日本語と順序が逆になる点が大切です。',['形容詞は名詞の後ろ：ร้านอร่อย「おいしい店」。','「この・その」は類別詞と使うことが多く、เครื่องนี้のような形もあります。'],[['มีร้านอร่อยแถวนี้ไหม','mii ráan arɔ̀i thɛ̌ɛo níi mǎi','この辺においしい店ある？','ร้าน＋อร่อยで「おいしい店」。'],['เครื่องนี้เก่าแล้ว','khrʉ̂aŋ níi kào lɛ́ɛo','この機械はもう古い。','เครื่องนี้は「この機械」。']], '「おいしい店」の基本の並びは？',['อร่อยร้าน','ร้านอร่อย','ร้านเป็นอร่อย'],1,'名詞ร้านの後ろに説明のอร่อยを置きます。');
L(0,'人・職業を言う เป็น／指し示す คือ','เป็น ＋ 属性 ／ คือ ＋ 特定内容','เป็นは職業・立場など「何に属するか」を表します。คือは説明や同定で「それは〜だ」と特定する表現です。',['職業はเป็น：เป็นช่าง「技術者・職人だ」。','คือは常に日本語の「です」と置き換える語ではありません。'],[['ผมเป็นคนญี่ปุ่น','phǒm pen khon yîipùn','私は日本人です。','人の属性を述べるเป็น。'],['นี่คือปัญหา','nîi khʉʉ panhǎa','これが問題です。','目の前の内容を問題だと特定。']], '「私は日本人です」の自然な形は？',['ผมเป็นคนญี่ปุ่น','ผมมีคนญี่ปุ่น','ผมอยู่คนญี่ปุ่น'],0,'国籍という属性を表すのでเป็นを使います。');
L(0,'ある・いる・持っている มี／อยู่','มี ＋ 名詞 ／ 人・物 ＋ อยู่ ＋ 場所','มีは存在や所有、อยู่は人や物の居場所を言うときに使います。「いる」という日本語だけで選ばず、何を伝えるかで選びます。',['場所＋มี＋名詞で「その場所には〜がある」。','人・物＋อยู่＋場所で「〜はそこにいる・ある」。'],[['มีร้านกาแฟแถวนี้','mii ráan kaafɛɛ thɛ̌ɛo níi','この辺にカフェがある。','存在を紹介するมี。'],['ผมอยู่ที่โรงงาน','phǒm yùu thîi rooŋŋaan','私は工場にいます。','居場所を述べるอยู่。']], '「私は工場にいる」の空欄：ผม ___ ที่โรงงาน',['มี','เป็น','อยู่'],2,'特定の人の居場所を言うときはอยู่です。');
L(1,'否定する ไม่／ไม่มี','ไม่ ＋ 動詞・状態 ／ ไม่มี ＋ 名詞','動作や状態を否定するなら、その前にไม่を置きます。「ない・持っていない」はไม่มีを使います。',['ไม่กิน「食べない」、ไม่ร้อน「暑くない」。','職業・国籍などの「〜ではない」は通常ไม่ใช่＋名詞。技能の「できない」は動詞＋ไม่เป็นです。'],[['วันนี้ไม่ว่าง','wan níi mâi wâaŋ','今日は暇じゃない。','状態ว่างをไม่で否定。'],['ไม่มีเวลา','mâi mii weelaa','時間がない。','所有・存在มีを否定。']], '「時間がない」は？',['ไม่เวลา','ไม่มีเวลา','เวลาไม่เป็น'],1,'名詞の存在を否定するのでไม่มีを使います。');
L(1,'はい・いいえを聞く ไหม','文 ＋ ไหม','文末にไหมを置くと、相手に答えを求める疑問文になります。肯定で答えるときは、動詞や状態の語を繰り返すと自然です。',['ว่างไหม「暇？」→ ว่าง「暇だよ」／ไม่ว่าง「暇じゃない」。','女性の丁寧な疑問の語尾はคะ。平叙文のค่ะとは声調が異なります。'],[['พรุ่งนี้ว่างไหม','phrûŋ níi wâaŋ mǎi','明日、空いてる？','相手の予定を聞く。'],['กินเผ็ดได้ไหม','kin phèt dâi mǎi','辛いもの食べられる？','ได้ไหมで可能かどうかを質問。']], 'ว่างไหม に「暇じゃない」と答えるなら？',['ไม่ว่าง','ไม่มีว่าง','ไหมว่าง'],0,'述語ว่างをไม่で否定して答えます。');
L(1,'何・どこ・いつ：疑問詞を置く位置','知りたい部分 → 疑問詞','疑問詞を英語のように毎回文頭へ移動しません。知りたい情報が入る位置にอะไร「何」、ที่ไหน「どこ」などを置きます。',['疑問詞がある文には、通常さらにไหมを付けません。','เมื่อไหร่「いつ」、กี่โมง「何時」を区別します。'],[['อยากกินอะไร','yàak kin arài','何を食べたい？','目的語の位置にอะไร。'],['ทำงานที่ไหน','tham ŋaan thîi nǎi','どこで働いてる？','場所を聞くที่ไหน。']], '「何を食べたい？」は？',['อยากกินอะไร','อะไรไหมอยากกิน','อยากอะไรไหมกิน'],0,'食べる対象の位置にอะไรを置きます。');
L(1,'選択を聞く หรือ／確認する ใช่ไหม','A หรือ B ／ 文 ＋ ใช่ไหม','หรือは「それとも」。ใช่ไหมは自分の理解が合っているか「〜だよね？」と確認します。',['選択肢を示すなら選択肢①หรือ選択肢②の形。','ใช่ไหมは予想の確認。情報がない状態の質問にはไหมが使いやすいです。'],[['เอาชาหรือกาแฟ','ao chaa rʉ̌ʉ kaafɛɛ','お茶にする？それともコーヒー？','相手に選んでもらう。'],['วันนี้ทำงานใช่ไหม','wan níi tham ŋaan châi mǎi','今日、仕事だよね？','仕事だと思って確認。']], '「今日仕事だよね？」と確認する文末は？',['ที่ไหน','ใช่ไหม','เมื่อไหร่'],1,'ใช่ไหมは、予想や認識が合っているかの確認です。');
L(1,'数える：数＋類別詞','名詞 ＋ 数 ＋ 類別詞','個数を言うときは「物・数・数え方」の順です。類別詞は、人・本・飲み物など対象によって変わります。',['人はคน、飲み物の一杯はแก้ว、一般的な小物ではอันなど。','กี่＋類別詞で「いくつ」。類別詞は名詞ごとに覚えましょう。'],[['เอากาแฟสองแก้ว','ao kaafɛɛ sɔ̌ɔŋ kɛ̂ɛo','コーヒーを2杯ください。','กาแฟ＋สอง＋แก้ว。'],['มีพนักงานกี่คน','mii phanákŋaan kìi khon','従業員は何人いますか？','人数を聞くกี่คน。']], '「コーヒー2杯」の順番は？',['กาแฟแก้วสอง','สองกาแฟแก้ว','กาแฟสองแก้ว'],2,'名詞＋数＋類別詞の順です。');
L(2,'これからする จะ','จะ ＋ 動詞','จะは予定・意図・予測など、まだ実現していないことを示します。未来の文でも、時間語で十分わかれば省かれることがあります。',['พรุ่งนี้「明日」などの時間語は文頭・文末に置けます。','จะは必ず実行するという保証ではありません。'],[['พรุ่งนี้จะไปกรุงเทพ','phrûŋ níi cà pai kruŋthêep','明日バンコクに行く予定。','これからの予定。'],['จะโทรหาทีหลัง','cà thoo hǎa thii lǎŋ','あとで電話するね。','後で行う意図。']], '「これから電話する」の空欄：___ โทรหา',['แล้ว','จะ','เคย'],1,'まだ実現していない予定や意図をจะで表します。');
L(2,'今している กำลัง…อยู่','กำลัง ＋ 動詞 ＋ อยู่','動作の進行を表します。กำลังだけ、または文末のอยู่だけでも、文脈により「〜している」を表せます。',['กำลังは動詞の前、อยู่は動作句の後ろ。','「住んでいる」などすべての日本語の「〜ている」にこの型を当てはめません。'],[['กำลังกินข้าวอยู่','kamlaŋ kin khâao yùu','今、ご飯を食べてる。','動作が進行中。'],['ทำอะไรอยู่','tham arài yùu','今、何してる？','日常でよく使う問いかけ。']], 'กำลังกินข้าวอยู่ の意味は？',['以前食べたことがある','今ご飯を食べている','明日ご飯を食べる'],1,'กำลัง…อยู่は動作の進行を表します。');
L(2,'もう・完了・変化 แล้ว','動作・状態 ＋ แล้ว','แล้วは完了だけでなく、「今はそうなった」という変化にも使います。過去の文すべてに必要な印ではありません。',['กินแล้ว「もう食べた」、หิวแล้ว「お腹が空いてきた」。','過去の出来事は昨日などの時間語だけでも示せます。'],[['กินข้าวแล้ว','kin khâao lɛ́ɛo','もうご飯食べた。','食事が済んでいる。'],['ถึงแล้วนะ','thʉ̌ŋ lɛ́ɛo ná','着いたよ。','到着したという新しい状況を知らせる。']], 'หิวแล้ว に近い意味は？',['お腹が空いてきた','空腹だったことがある','絶対に空腹にならない'],0,'แล้วは状態の変化も表します。');
L(2,'まだ・まだ〜ない ยัง／ยังไม่','ยัง ＋ 状態 ／ ยังไม่ ＋ 動詞','ยังは状態が続く「まだ」、ยังไม่はあることが未実現で「まだ〜ない」を表します。',['ยังอยู่「まだいる」とยังไม่อยู่は別の意味。','完了を聞くหรือยัง「もう〜した？」と対にして覚えると便利です。'],[['ยังไม่เสร็จ','yaŋ mâi sèt','まだ終わってない。','完了していない状態。'],['กินข้าวหรือยัง','kin khâao rʉ̌ʉ yaŋ','もうご飯食べた？','แล้ว「食べた」／ยัง「まだ」で答えられます。']], '「まだ終わっていない」は？',['ไม่เสร็จแล้ว','ยังไม่เสร็จ','เสร็จยังไม่'],1,'ยังไม่＋動詞で「まだ〜していない」。');
L(2,'経験がある เคย／一度もない ไม่เคย','เคย ＋ 動詞 ／ ไม่เคย ＋ 動詞','過去の一回の出来事ではなく、「〜したことがある」という経験に焦点を当てます。',['เคยの否定はไม่เคย。「まだ」のยังไม่と区別しましょう。','เคย…ไหมで経験を質問できます。'],[['เคยไปเชียงใหม่ไหม','khəəi pai chiaŋ mài mǎi','チェンマイに行ったことある？','過去の経験を聞く。'],['ไม่เคยกินอันนี้','mâi khəəi kin an níi','これは食べたことがない。','経験がないことを伝える。']], '「行ったことがない」は？',['ไม่เคยไป','ยังไป','ไปแล้ว'],0,'ไม่เคยは「これまで経験がない」を表します。');
L(3,'したい อยาก／欲しい อยากได้','อยาก ＋ 動詞 ／ อยากได้ ＋ 物','自分の希望を伝える基本表現。動作の希望はอยาก、物が欲しいならอยากได้を使います。',['อยากกิน「食べたい」、อยากได้อันนี้「これが欲しい」。','強い要求ではなく気持ちとして「〜したい」を伝えられます。'],[['อยากกลับบ้าน','yàak klàp bâan','家に帰りたい。','อยาก＋帰る。'],['อยากได้อันนี้','yàak dâi an níi','これが欲しい。','物を手に入れたいという希望。']], '「家に帰りたい」の空欄：___ กลับบ้าน',['อยาก','เคยไหม','คือ'],0,'動作の希望はอยาก＋動詞で表します。');
L(3,'できる ได้／やり方を知る เป็น','動詞 ＋ ได้ ／ 動詞 ＋ เป็น','ได้は状況上の可能・許可など、เป็นは身につけた技能や方法を知っていることを表します。',['ขับรถเป็น「運転の仕方を知っている」、ขับรถได้「運転できる」。意味が重なる場面もあります。','ไม่ได้＋動詞は「〜しなかった・〜ではない」という別の用法もあり、位置が大切です。'],[['วันนี้ไปไม่ได้','wan níi pai mâi dâi','今日は行けない。','事情があって実行できない。'],['ขับรถเป็นไหม','khàp rót pen mǎi','車の運転できる？','技能があるかを聞く。']], '「事情があって今日は行けない」は？',['วันนี้ไปไม่ได้','วันนี้ไปไม่เคย','วันนี้ไม่มีไป'],0,'動詞＋ไม่ได้で実行が不可能なことを表します。');
L(3,'必要・助言 ต้อง／ควร','ต้อง ＋ 動詞 ／ ควร ＋ 動詞','ต้องは「〜しなければならない」。ควรは「〜したほうがいい」という助言や望ましさを表します。',['ไม่ต้องは「〜しなくていい」。禁止とは異なります。','禁止はห้าม、直接やめてと言うならอย่าを使います。'],[['พรุ่งนี้ต้องทำงาน','phrûŋ níi tɔ̂ŋ tham ŋaan','明日は仕事をしなければならない。','必要や義務。'],['ไม่ต้องรีบ','mâi tɔ̂ŋ rîip','急がなくていいよ。','急ぐ必要がないと伝える。']], 'ไม่ต้องรีบ の意味は？',['急がなくていい','急いではいけないと強く禁止','必ず急がないといけない'],0,'ไม่ต้องは不要を表します。禁止のห้ามとは違います。');
L(3,'頼む ช่วย…หน่อย／…ให้หน่อย','ช่วย ＋ 動詞 ＋ หน่อย','ช่วย…หน่อยは相手に手伝いや行動をお願いする自然な形です。ให้を動作の後ろに置くと「こちらのために」の意味を添えられます。',['หน่อยは直訳の「少し」だけでなく、依頼をやわらげる働きがあります。','チェックしてほしいならช่วยเช็กให้หน่อย。仕事で丁寧にするなら文末にครับ / ค่ะを添えます。'],[['ช่วยพูดช้า ๆ หน่อย','chûai phûut cháa cháa nɔ̀i','少しゆっくり話して。','ช่วยとหน่อยで依頼。'],['เช็กให้หน่อย','chék hâi nɔ̀i','ちょっと確認してくれる？','ให้は受益、หน่อยは依頼のやわらげ。เช็กは英語 check 由来。']], '「少しゆっくり話して」の自然な依頼は？',['ช่วยพูดช้า ๆ หน่อย','พูดช่วยหน่อยช้า','หน่อยพูดช่วยช้า'],0,'ช่วย＋動作＋หน่อยが依頼の基本形です。');
L(3,'試してみる ลอง…ดู／先にする ก่อน','ลอง ＋ 動詞 ＋ ดู ／ 動作 ＋ ก่อน','ลอง…ดูは「試しに〜してみる」。文末のดูは、ここでは「見る」という独立した動作ではなく、試行の意味を補います。',['ก่อนは「先に」「ひとまず」。文脈で順番や暫定的な対応を表します。','ลองถามคนอื่นดู「他の人に聞いてみて」のดูも試行を表します。'],[['ลองถามคนอื่นดู','lɔɔŋ thǎam khon ʉ̀ʉn duu','他の人に聞いてみて。','ลอง…ดูで試すことを勧める。'],['รอดูก่อน','rɔɔ duu kɔ̀ɔn','ひとまず様子を見よう。','ก่อนでいったん待つ姿勢を表す。']], 'ลองถามคนอื่นดู のดูは？',['必ず目で見るという意味だけ','試しにやってみる意味を添える','過去を表す'],1,'ลองと組み合わせて、試行を表します。');
L(4,'比較する กว่า／いちばん ที่สุด','状態 ＋ กว่า ／ 状態 ＋ ที่สุด','比較は形容詞・状態を表す語の後ろにกว่าを置きます。比較対象を続けると「〜より」を明示できます。',['เร็วกว่า「より速い」、ดีกว่า「よりよい」。','ที่สุดは「最も」。比較の範囲は文脈やใน…で補います。'],[['รถไฟฟ้าเร็วกว่าแท็กซี่','rót fai fáa reo kwàa thɛ́ksîi','電車のほうがタクシーより速い。','比較される対象はกว่าの後ろ。'],['อันนี้ดีที่สุด','an níi dii thîi sùt','これがいちばんいい。','ที่สุดで最上級。']], '「より速い」の並びは？',['กว่าเร็ว','เร็วกว่า','ที่สุดกว่าเร็ว'],1,'状態の語เร็วの後ろにกว่าを置きます。');
L(4,'理由と結果 เพราะ／ก็เลย','結果 เพราะ 理由 ／ 原因 ก็เลย 結果','เพราะは理由、ก็เลยはその結果起きたことをつなぎます。会話で「雨だから電車にする」のような説明に使えます。',['เพราะ＋理由は文頭にも置けます。','ก็เลยは「それで」。必ず同じ文でเพราะと組み合わせる必要はありません。'],[['ไปไม่ได้เพราะต้องทำงาน','pai mâi dâi phrɔ́ tɔ̂ŋ tham ŋaan','仕事があるから行けない。','結果の後に理由を補う。'],['ฝนตกก็เลยนั่งรถไฟฟ้า','fǒn tòk kɔ̂ ləəi nâŋ rót fai fáa','雨が降っているので電車に乗る。','原因から結果へ。']], 'เพราะ が導く内容は？',['理由','最上級','経験'],0,'เพราะは「なぜなら・〜なので」と理由を示します。');
L(4,'条件を言う ถ้า…ก็…','ถ้า ＋ 条件 ＋ ก็ ＋ 結果','ถ้าは「もし〜なら」。その条件でどうするかを続けます。結果の前のก็は省かれることもあります。',['予定が確定していることを述べるだけなら、毎回ถ้าは要りません。','ถ้าの後ろに主語・否定・動詞などを含む節を置けます。'],[['ถ้าว่างก็ไปด้วยกัน','thâa wâaŋ kɔ̂ pai dûai kan','暇なら一緒に行こう。','条件に応じた誘い。'],['ถ้าฝนตกจะไม่ไป','thâa fǒn tòk cà mâi pai','雨が降ったら行かない。','ก็を省いた条件文。']], '「もし暇なら」の空欄：___ ว่าง',['เพราะ','ถ้า','กว่า'],1,'条件を示すのはถ้าです。');
L(4,'名詞を詳しくする ที่','名詞 ＋ ที่ ＋ 説明する節','「昨日買った物」「ここで働いている人」のように、文で名詞を説明するときはที่でつなぎます。',['日本語は説明が名詞の前、タイ語は名詞の後ろ。','ที่は場所を示すときもありますが、この型では説明をつなぐ働きです。'],[['คนที่ทำงานที่นี่เป็นเพื่อนผม','khon thîi tham ŋaan thîi nîi pen phʉ̂an phǒm','ここで働いている人は私の友達です。','最初のที่は修飾、ที่นี่は「ここ」。'],['ร้านที่ไปเมื่อวานอร่อยมาก','ráan thîi pai mʉ̂a waan arɔ̀i mâak','昨日行った店はとてもおいしい。','ร้านを「昨日行った」で説明。']], '「昨日行った店」の語順は？',['ร้านที่ไปเมื่อวาน','ที่ร้านเมื่อวานไป','เมื่อวานที่ร้านเป็น'],0,'名詞ร้าน＋ที่＋説明節の順です。');
L(4,'と言う・と思う ว่า','言う・思う ＋ ว่า ＋ 内容','ว่าは発言や考えの内容をつなぐ語です。คิดว่า「〜と思う」、บอกว่า「〜と言う」の形でよく使います。',['後ろには主語を含む文を置けます。','「〜と思う」でも推測ならน่าจะを使うことがあり、確信の強さは文脈で変わります。'],[['คิดว่าพรุ่งนี้จะว่าง','khít wâa phrûŋ níi cà wâaŋ','明日は暇だと思う。','思っている内容をว่าでつなぐ。'],['เขาบอกว่าจะมาช้า','khǎo bɔ̀ɔk wâa cà maa cháa','あの人は来るのが遅くなると言っていた。','伝達内容を示すว่า。']], '「〜と思う」のつなぎ方は？',['คิดที่','คิดว่า','คิดกว่า'],1,'คิดว่าの後ろに思っている内容を置きます。');
L(5,'してあげる ให้／させる ให้','動詞 ＋ ให้ ＋ 相手 ／ ให้ ＋ 人 ＋ 動詞','ให้は「与える」のほか、動作の後ろで受益者を示し、動作の前では「〜にさせる・してもらう」などを表します。位置と文脈が重要です。',['ซื้อให้แม่「母に買ってあげる」は動詞＋ให้＋受益者。','ให้เขาทำ「彼にやってもらう・させる」はให้＋行為者＋動詞。'],[['ซื้อขนมให้เพื่อน','sʉ́ʉ khanǒm hâi phʉ̂an','友達にお菓子を買ってあげる。','動作の利益を受ける相手がให้の後ろ。'],['ให้เขาลองทำก่อน','hâi khǎo lɔɔŋ tham kɔ̀ɔn','まず彼にやってもらおう。','ให้の後ろが実際にやる人。']], 'ให้เขาทำ で実際に作業するのは？',['เขา（彼・その人）','常に話し手だけ','誰も作業しない'],0,'ให้＋人＋動詞では、その人が後ろの動作を行います。');
L(5,'原因が変化を起こす ทำให้','原因 ＋ ทำให้ ＋ 結果','ทำให้は「〜を引き起こす・〜にする」。人の命令ではなく、出来事が状態や結果を生むときにも使えます。',['ทำให้ดีใจ「うれしくさせる」。結果は動詞や状態を含む節です。','ให้ทำ「やらせる」とทำให้「結果を生む」は語順も働きも異なります。'],[['ฝนตกทำให้รถติด','fǒn tòk tham hâi rót tìt','雨で渋滞が起きている。','雨が渋滞という結果を生む。'],['เรื่องนี้ทำให้เครียด','rʉ̂aŋ níi tham hâi khrîat','このことがストレスになる。','結果の状態はเครียด。']], '「雨が渋滞を引き起こす」の接続は？',['ฝนตกทำให้รถติด','ฝนตกให้ทำรถติด','ฝนตกกว่ารถติด'],0,'原因＋ทำให้＋結果の構造です。');
L(5,'推測する น่าจะ／かもしれない อาจจะ','น่าจะ ＋ 動詞 ／ อาจจะ ＋ 動詞','น่าจะは「おそらく〜だろう」と見込みを述べます。อาจจะは「〜かもしれない」と可能性を示します。確率の数値は決まっていません。',['น่าจะは根拠や予想を伴う場面によく使います。','「たぶん」をมันだけで表しません。มันは物や事柄などを指す代名詞です。'],[['น่าจะถึงประมาณสองทุ่มครึ่ง','nâa cà thʉ̌ŋ pràmaan sɔ̌ɔŋ thûm khrʉ̂ŋ','たぶん20時半ごろ着く。','到着の見込みを伝える。'],['พรุ่งนี้อาจจะไม่ว่าง','phrûŋ níi àat cà mâi wâaŋ','明日は空いていないかもしれない。','確定していない可能性。']], '「おそらく着くだろう」と見込みを言うなら？',['น่าจะถึง','มันถึง（มันだけで「たぶん」）','ถึงที่สุด'],0,'見込みを表すน่าจะを使います。มันだけには「たぶん」の意味はありません。');
L(5,'受け身・影響を受ける ถูก','人・物 ＋ ถูก ＋ 動詞','ถูก＋動詞は、他者から行為を受けたことを示します。好ましくない出来事でよく使われますが、それだけに限定されません。',['ถูกชม「ほめられる」のような良い出来事にも使えます。','ถูกには単独で「正しい」「安い」の意味もあるため、形で判断します。'],[['เขาถูกหลอก','khǎo thùuk lɔ̀ɔk','あの人はだまされた。','他者の行為を受ける。'],['วันนี้ถูกชม','wan níi thùuk chom','今日はほめられた。','望ましい出来事にも使える例。']], 'ถูกชม の意味は？',['ほめられる','安くほめる','ほめるべきだ'],0,'ถูก＋動詞で行為を受けることを表します。');
L(5,'文末の温度感 นะ／สิ／เหรอ','文 ＋ 会話の助詞','文末の助詞は話し手の態度や相手との距離感を添えます。日本語と一対一対応せず、声の調子にも左右されます。',['นะは念押し・共有・やわらげ。命令を必ず丁寧にする万能語ではありません。','สิは促し・強調で強く響く場合も。เหรอは「そうなの？」という問い返し・意外さを表します。'],[['พักก่อนนะ','phák kɔ̀ɔn ná','先にちょっと休むね／休んでね。','主語を省いているため、文脈で話し手の宣言にも相手への声かけにもなる。'],['จริงเหรอ','ciŋ rə̌ə','本当なの？','意外さや確認を込めた問い返し。']], 'จริงเหรอ が自然に表すのは？',['本当なの？という問い返し','絶対に禁止すること','過去の経験'],0,'เหรอは問い返しや意外さを伴う確認に使います。');
